//! Video facts from the `moov` box of an MP4 / MOV / M4V file.
//!
//! Chosen over AVFoundation through the shell because it needs no OS call,
//! runs on any thread, reads a few kilobytes by seeking (the `moov` box may
//! sit at the end of a 50 GB file), and is testable with generated bytes.
//! The cost: only ISO-base-media files (MP4, MOV, M4V, 3GP, and the Canon
//! CR3 container) are understood; MKV, AVI and MXF show no video facts.

use std::fs::File;
use std::io::{Read, Seek};
use std::path::Path;

use crate::cancel::CancelToken;
use crate::iso::{self, BoxRef, be16, be32, be64};
use crate::types::VideoInfo;

/// What one `trak` says.
#[derive(Debug, Clone, Default, PartialEq)]
pub(crate) struct Track {
    /// `vide`, `soun`, …
    pub handler: [u8; 4],
    /// The sample format code (`avc1`, `hvc1`, `mp4a`, `CRAW`…).
    pub format: [u8; 4],
    /// Pixel size from the sample description (video tracks).
    pub width: u32,
    /// Pixel height.
    pub height: u32,
    /// Samples in the track (from `stts`).
    pub samples: u64,
    /// Media time scale (units per second).
    pub timescale: u32,
    /// Media duration in time-scale units.
    pub duration: u64,
}

/// The movie header's time scale and duration.
fn mvhd(p: &[u8]) -> Option<(u32, u64)> {
    match *p.first()? {
        0 => Some((be32(p, 12)?, u64::from(be32(p, 16)?))),
        1 => Some((be32(p, 20)?, be64(p, 24)?)),
        _ => None,
    }
}

fn mdhd(p: &[u8]) -> Option<(u32, u64)> {
    mvhd(p) // same layout
}

/// Reads every `trak` inside a `moov` box.
pub(crate) fn tracks<R: Read + Seek>(r: &mut R, moov: &BoxRef) -> Vec<Track> {
    let mut out = Vec::new();
    for trak in iso::children(r, moov.payload, moov.end)
        .into_iter()
        .filter(|b| &b.kind == b"trak")
    {
        let Some(mdia) = iso::find(r, &trak, b"mdia") else {
            continue;
        };
        let mut t = Track::default();
        if let Some(b) = iso::find(r, &mdia, b"mdhd")
            && let Some(p) = iso::payload(r, &b, 64)
            && let Some((ts, d)) = mdhd(&p)
        {
            t.timescale = ts;
            t.duration = d;
        }
        if let Some(b) = iso::find(r, &mdia, b"hdlr")
            && let Some(p) = iso::payload(r, &b, 32)
            && let Some(h) = p.get(8..12)
        {
            t.handler = [h[0], h[1], h[2], h[3]];
        }
        if let Some(minf) = iso::find(r, &mdia, b"minf")
            && let Some(stbl) = iso::find(r, &minf, b"stbl")
        {
            if let Some(b) = iso::find(r, &stbl, b"stsd")
                && let Some(p) = iso::payload(r, &b, 256)
                && let Some(f) = p.get(12..16)
            {
                t.format = [f[0], f[1], f[2], f[3]];
                if &t.handler == b"vide" || &t.format == b"CRAW" {
                    t.width = u32::from(be16(&p, 40).unwrap_or(0));
                    t.height = u32::from(be16(&p, 42).unwrap_or(0));
                }
            }
            if let Some(b) = iso::find(r, &stbl, b"stts")
                && let Some(p) = iso::payload(r, &b, 1 << 20)
            {
                let n = be32(&p, 4).unwrap_or(0) as usize;
                let mut total = 0u64;
                for i in 0..n.min((p.len().saturating_sub(8)) / 8) {
                    total += u64::from(be32(&p, 8 + i * 8).unwrap_or(0));
                }
                t.samples = total;
            }
        }
        out.push(t);
    }
    out
}

/// A readable name for a sample format code.
pub(crate) fn codec_name(f: &[u8; 4]) -> String {
    let s = match f {
        b"avc1" | b"avc3" => "H.264",
        b"hvc1" | b"hev1" => "HEVC",
        b"dvh1" | b"dvhe" => "HEVC (Dolby Vision)",
        b"av01" => "AV1",
        b"vp09" => "VP9",
        b"apch" => "Apple ProRes 422 HQ",
        b"apcn" => "Apple ProRes 422",
        b"apcs" => "Apple ProRes 422 LT",
        b"apco" => "Apple ProRes 422 Proxy",
        b"ap4h" => "Apple ProRes 4444",
        b"ap4x" => "Apple ProRes 4444 XQ",
        b"mp4v" => "MPEG-4 Visual",
        b"jpeg" | b"mjpa" | b"mjpb" => "Motion JPEG",
        b"mp4a" => "AAC",
        b"alac" => "Apple Lossless",
        b"ac-3" => "AC-3",
        b"ec-3" => "E-AC-3",
        b"Opus" => "Opus",
        b"fLaC" => "FLAC",
        b"lpcm" | b"sowt" | b"twos" | b"in24" | b"in32" | b"fl32" | b"fl64" => "PCM",
        _ => {
            let t: String = f
                .iter()
                .map(|&b| if b.is_ascii_graphic() { b as char } else { '?' })
                .collect();
            return t;
        }
    };
    s.to_string()
}

/// `1:23:45` or `0:42`.
pub(crate) fn format_duration(secs: f64) -> String {
    let total = secs.max(0.0).round() as u64;
    let (h, m, s) = (total / 3600, (total / 60) % 60, total % 60);
    if h > 0 {
        format!("{h}:{m:02}:{s:02}")
    } else {
        format!("{m}:{s:02}")
    }
}

/// `29.97 fps`, `24 fps`, `25 fps`.
pub(crate) fn format_fps(fps: f64) -> String {
    let rounded = (fps * 100.0).round() / 100.0;
    if (rounded - rounded.round()).abs() < 0.005 {
        format!("{} fps", rounded.round() as u64)
    } else {
        format!("{rounded:.2} fps")
    }
}

/// Reads video facts from `path`. The note says why there are none.
pub(crate) fn read(path: &Path, cancel: &CancelToken) -> (Option<VideoInfo>, Option<String>) {
    let Ok(mut f) = File::open(path) else {
        return (None, Some("Can't read this file".into()));
    };
    let Ok(len) = f.metadata().map(|m| m.len()) else {
        return (None, None);
    };
    let top = iso::children(&mut f, 0, len);
    if cancel.is_cancelled() {
        return (None, None);
    }
    let known = top.iter().any(|b| {
        matches!(
            &b.kind,
            b"ftyp" | b"moov" | b"mdat" | b"wide" | b"free" | b"skip"
        )
    });
    if !known {
        return (None, None);
    }
    let Some(moov) = top.iter().find(|b| &b.kind == b"moov").copied() else {
        return (
            None,
            Some("The movie's header is missing or cut short".into()),
        );
    };
    let info = video_info(&mut f, &moov);
    if info == VideoInfo::default() {
        (None, Some("No video details found".into()))
    } else {
        (Some(info), None)
    }
}

fn video_info<R: Read + Seek>(r: &mut R, moov: &BoxRef) -> VideoInfo {
    let mut info = VideoInfo::default();
    let movie_secs = iso::find(r, moov, b"mvhd")
        .and_then(|b| iso::payload(r, &b, 64))
        .and_then(|p| mvhd(&p))
        .filter(|(ts, _)| *ts > 0)
        .map(|(ts, d)| d as f64 / f64::from(ts));
    let tr = tracks(r, moov);
    if let Some(v) = tr.iter().find(|t| &t.handler == b"vide") {
        info.codec = Some(codec_name(&v.format));
        if v.width > 0 && v.height > 0 {
            info.width = Some(v.width);
            info.height = Some(v.height);
            info.resolution = Some(format!("{} × {}", v.width, v.height));
        }
        let track_secs = (v.timescale > 0).then(|| v.duration as f64 / f64::from(v.timescale));
        if let Some(secs) = track_secs.filter(|s| *s > 0.0)
            && v.samples > 1
        {
            info.frame_rate = Some(format_fps(v.samples as f64 / secs));
        }
        info.duration_secs = movie_secs.or(track_secs);
    } else {
        info.duration_secs = movie_secs;
    }
    info.duration = info.duration_secs.map(format_duration);
    if let Some(a) = tr.iter().find(|t| &t.handler == b"soun") {
        info.audio = Some(codec_name(&a.format));
    }
    info
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::iso::testutil::make_box;
    use std::io::Cursor;

    fn be(n: u32) -> Vec<u8> {
        n.to_be_bytes().to_vec()
    }

    /// A tiny movie: 10 s at 600 units/s, a 1920×1080 `avc1` track with 300
    /// frames (30 fps) and an `mp4a` track.
    pub(crate) fn sample_movie() -> Vec<u8> {
        let mut mvhd_p = vec![0u8; 4];
        mvhd_p.extend([be(0), be(0), be(600), be(6000)].concat());
        mvhd_p.extend(vec![0u8; 80]);
        let track = |handler: &[u8; 4], fmt: &[u8; 4], w: u16, h: u16, frames: u32| {
            let mut mdhd_p = vec![0u8; 4];
            mdhd_p.extend([be(0), be(0), be(600), be(6000)].concat());
            let mut hdlr_p = vec![0u8; 8];
            hdlr_p.extend(handler);
            hdlr_p.extend(vec![0u8; 12]);
            let mut entry = be(0);
            entry.extend(fmt);
            entry.extend(vec![0u8; 6]);
            entry.extend([0, 1]);
            entry.extend(vec![0u8; 16]);
            entry.extend(w.to_be_bytes());
            entry.extend(h.to_be_bytes());
            let mut stsd_p = be(0);
            stsd_p.extend(be(1));
            stsd_p.extend(entry);
            let mut stts_p = be(0);
            stts_p.extend(be(1));
            stts_p.extend(be(frames));
            stts_p.extend(be(20));
            let stbl = [make_box(b"stsd", &stsd_p), make_box(b"stts", &stts_p)].concat();
            let minf = make_box(b"minf", &make_box(b"stbl", &stbl));
            let mdia = make_box(
                b"mdia",
                &[make_box(b"mdhd", &mdhd_p), make_box(b"hdlr", &hdlr_p), minf].concat(),
            );
            make_box(b"trak", &mdia)
        };
        let moov = make_box(
            b"moov",
            &[
                make_box(b"mvhd", &mvhd_p),
                track(b"vide", b"avc1", 1920, 1080, 300),
                track(b"soun", b"mp4a", 0, 0, 100),
            ]
            .concat(),
        );
        [
            make_box(b"ftyp", b"isom\0\0\0\0isom"),
            make_box(b"mdat", &[0; 16]),
            moov,
        ]
        .concat()
    }

    #[test]
    fn reads_codec_size_duration_and_frame_rate() {
        let bytes = sample_movie();
        let mut c = Cursor::new(bytes.clone());
        let top = iso::children(&mut c, 0, bytes.len() as u64);
        let moov = top.iter().find(|b| &b.kind == b"moov").unwrap();
        let v = video_info(&mut c, moov);
        assert_eq!(v.codec.as_deref(), Some("H.264"));
        assert_eq!(v.resolution.as_deref(), Some("1920 × 1080"));
        assert_eq!(v.duration.as_deref(), Some("0:10"));
        assert_eq!(v.frame_rate.as_deref(), Some("30 fps"));
        assert_eq!(v.audio.as_deref(), Some("AAC"));
    }

    #[test]
    fn formats() {
        assert_eq!(format_duration(3725.4), "1:02:05");
        assert_eq!(format_duration(42.0), "0:42");
        assert_eq!(format_fps(29.97002997), "29.97 fps");
        assert_eq!(format_fps(23.976), "23.98 fps");
        assert_eq!(format_fps(25.0), "25 fps");
    }

    #[test]
    fn truncated_movie_does_not_panic() {
        let bytes = sample_movie();
        for cut in [0, 5, 20, 60, bytes.len() - 30, bytes.len() - 1] {
            let mut c = Cursor::new(bytes[..cut].to_vec());
            let top = iso::children(&mut c, 0, cut as u64);
            if let Some(m) = top.iter().find(|b| &b.kind == b"moov") {
                let _ = video_info(&mut c, m);
            }
        }
    }
}
